export function compoundProjection(initial,monthly,years,annualPct){
 if(![initial,monthly,years,annualPct].every(Number.isFinite)||initial<0||monthly<0||initial>1e6||monthly>1e6||!Number.isInteger(years)||years<1||years>40||annualPct< -20||annualPct>20)throw Error('Revisa los números del laboratorio.');
 let value=initial;const series=[];
 for(let month=1;month<=years*12;month++){value=value*(1+annualPct/1200)+monthly;if(month%12===0)series.push({year:month/12,contributed:initial+monthly*month,value});}
 const contributed=initial+monthly*years*12;return {value,contributed,gain:value-contributed,series};
}
